function tallestFirst(names: string[], heights: number[]): string[] {
  const used = new Array(names.length).fill(false), out: string[] = [];
  for (let k = 0; k < names.length; k++) {
    let best = -1;
    for (let i = 0; i < names.length; i++) {
      if (!used[i] && (best < 0 || heights[i] > heights[best])) best = i;
    }
    used[best] = true;
    out.push(names[best]);
  }
  return out;
}

