class Solution:
    def tallestFirst(self, names: List[str], heights: List[int]) -> List[str]:
        used, out = [False] * len(names), []
        for _ in range(len(names)):
            best = -1
            for i in range(len(names)):
                if not used[i] and (best < 0 or heights[i] > heights[best]):
                    best = i
            used[best] = True
            out.append(names[best])
        return out

